srcText:
// Glance → the stream morph view, AS GRAPH SOURCE (#4185, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui
// design system + the store via appModules, the glance lib/hook surface via the glance graph-platform,
// and the sibling components as @/components/* graph records). Behaviour runs here.
// GlanceStreamMorph (#2401, #2534) — a live agent node GROWING in place into its CLI session, IN the
// graph. The expanded terminal is a WORLD-LAYER child ANCHORED at the node's world coords, so it pans
// with the graph — the rest of the fleet stays visible + interactive. No portal, no scrim: the graph
// never leaves; a node just gains a second state. The card animates GEOMETRY (left/top/width/height)
// from the node's box to an expanded panel hosting the SAME GlanceChatDock (the real PTY stream — the
// terminal is the input surface, #3523). It's RESIZABLE from every EDGE and CORNER (standard window
// handles) and REPORTS its world box up (`onRect`) so the canvas can push overlapping neighbour nodes
// out of the way (#2662). Esc or the dock's ✕ shrinks it back into the node. Reduced-motion → an instant
// swap (the CSS zeroes the transitions; the fallback timer still fires onClose). Closing UNMOUNTS the
// TerminalView, which keeps its PTY alive (cleanup is kill-free), so the agent is untouched.
//
// THE CARD IS A CONSTANT SCREEN SIZE — it no longer SCALES with the graph
// (`the-in-graph-terminal-cannot-be-clicked-accurately-under-zoom`, revising #2534 option A).
//
// It has to be, and the reason is not taste. This card hosts a live xterm, and xterm resolves a click to
// a cell by dividing a TRANSFORM-ADJUSTED offset (`getBoundingClientRect`) by an UNSCALED cell width
// (`CharSizeService.measure` reads `offsetWidth`, which ignores transforms). Those two agree only at net
// CSS scale 1. Under the world layer's `scale(view.scale)` every click therefore landed off by the zoom
// — MEASURED across the whole [0.28, 2.6] range in `e2e/xtermScale.spec.ts`, and worse than a simple
// offset above 1: `getMouseReportCoords` clamps to the UNSCALED canvas width, so the right-hand part of
// a zoomed-in terminal collapsed onto its last column and could not be clicked at all.
//
// THE SHAPE, and why it is two elements rather than one:
//
//   ANCHOR  — positioned in WORLD coords at the grid anchor's centre, and carrying `scale(1/view.scale)`
//             written by `vp.counterScale`. Net CSS scale on everything inside is 1, so xterm is correct
//             by construction. The hook owns that transform because #4140 drives the world layer
//             imperatively, and a `scale(1/zoom)` computed here from the `zoom` PROP would be stale for
//             the whole of every wheel gesture — un-clickable exactly while the user zooms in to click.
//   CARD    — inside it, in SCREEN px (left/top/width/height). Its own transition still animates those
//             four properties, so the grow/shrink motion and `glance.css` are untouched.
//
// The alternative — keep scaling and counter-fix the terminal — is #3524, which was merged and reverted
// eight minutes later: counter-scaling the terminal changes its cols/rows, so it ran `fit()` +
// `pty_resize` on every wheel notch, into every open agent's PTY, in a repo that already carries #2832
// and #3996 for exactly that.
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { CSSProperties } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { anchorCentre, cellOffset, cellRect, clampCell, type CellSize, type GridCell } from "@/features/glance/lib/morphGrid";
import { GlanceChatDock, type DockPlan } from "@/components/glance-chat-dock";
import { NW, NH } from "@/features/glance/lib/glanceGraph";
import type { MorphRect } from "@/features/glance/lib/glancePush";

/** Grow/shrink duration (ms) — the reduced-motion fallback for onClose. Keep in sync with the
 *  `.glance-card` transition in glance.css. */
const EXIT_MS = 420;
// Card geometry lives in `lib/morphGrid` since #3361 — the SLOT the morph grows into is computed by the
// grid, and resize drives the grid's shared cell size rather than this one card's box.

/** The eight resize handles: which edges each grip drives, its box within the card, and its cursor. */
const HANDLES: { dir: string; style: CSSProperties }[] = (() => {
  const E = 8, C = 15;                                   // edge thickness · corner size (screen px)
  const ns = "ns-resize", ew = "ew-resize", nwse = "nwse-resize", nesw = "nesw-resize";
  return [
    { dir: "n",  style: { top: -E / 2, left: C, right: C, height: E, cursor: ns } },
    { dir: "s",  style: { bottom: -E / 2, left: C, right: C, height: E, cursor: ns } },
    { dir: "w",  style: { left: -E / 2, top: C, bottom: C, width: E, cursor: ew } },
    { dir: "e",  style: { right: -E / 2, top: C, bottom: C, width: E, cursor: ew } },
    { dir: "nw", style: { top: -E / 2, left: -E / 2, width: C, height: C, cursor: nwse } },
    { dir: "se", style: { bottom: -E / 2, right: -E / 2, width: C, height: C, cursor: nwse } },
    { dir: "ne", style: { top: -E / 2, right: -E / 2, width: C, height: C, cursor: nesw } },
    { dir: "sw", style: { bottom: -E / 2, left: -E / 2, width: C, height: C, cursor: nesw } },
  ];
})();

export function GlanceStreamMorph({ node, anchorNode, at, cell, paneId, name, role, plan, zoom = 1, counterScale, onRect, onResizeCell, onClose, onEnd }: {
  /** The graph node this session belongs to — the card's origin + return box, in WORLD coords. */
  node: { x: number; y: number };
  /** The node the whole GRID hangs from (#3361) — every open morph shares it, and the anchor element is
   *  positioned at its centre. For the FIRST opened node this is its own node, so a single open morph
   *  lands exactly where it always has. */
  anchorNode: { x: number; y: number };
  /** This morph's LATTICE CELL. Signed: `col: -1` is one cell left of the anchor. Replaces the old
   *  world-space `slot` rect — the box is now derived here, because it is two different boxes (a screen
   *  one to render and a world one to report) and computing them apart is how they drift. */
  at: GridCell;
  /** The grid's SHARED cell size, in SCREEN px. */
  cell: CellSize;
  /** The agent's identity pane id (`<project>:<stream>`) — the live PTY the dock reconnects to. */
  paneId: string;
  name: string;
  role?: string;
  /** This worker's owned issues (#4102) — forwarded to the dock's Plan screen. */
  plan?: DockPlan;
  /** The graph's current zoom (`vp.view.scale`). Used ONLY for the two things that genuinely need a
   *  world↔screen conversion: the world box reported to the neighbour push, and the COLLAPSED endpoint
   *  of the grow animation (which must match the node's on-screen box). Deliberately NOT used for the
   *  counter-scale or for the open card's geometry — this value is committed 120ms after a wheel settles
   *  (#4140), so anything that must track a live gesture cannot come from here. */
  zoom?: number;
  /** `vp.counterScale` — registers the anchor element so the hook writes `scale(1/view.scale)` on it in
   *  the same call that moves the world layer. Absent ⇒ no counter-scale, which is only correct for a
   *  test that never zooms. */
  counterScale?: (el: HTMLElement) => () => void;
  /** Report the expanded WORLD box (or null when collapsed/closed) so the canvas can push neighbours
   *  (#2662). With several morphs open the canvas unions every reported box (#3361). Since the card is a
   *  constant screen size, this box GROWS as the graph zooms out — reporting the nominal cell instead is
   *  what let a zoomed-out panel cover the very nodes it was supposed to part. */
  onRect?: (rect: MorphRect | null) => void;
  /** A resize drag, in SCREEN px — drives the grid's SHARED cell size, so every open morph resizes
   *  together (#3361). A per-morph size would let two cells grow into each other, breaking the
   *  non-overlap guarantee the grid exists to provide. */
  onResizeCell?: (w: number, h: number) => void;
  /** Collapse the morph back into its node (keeps the PTY alive). */
  onClose: () => void;
  /** END the session — kill the PTY + drop the cell from the live set (#3049) — for a soft-locked
   *  fleet the user needs to fully tear a stuck agent down before relaunching triage. Undefined ⇒
   *  the dock omits the affordance. */
  onEnd?: () => void;
}) {
  const [open, setOpen] = useState(false);
  // The grid owns placement (so morphs can't overlap) and the shared cell size (so a resize moves them
  // as one) — none of it is local state (#3361).
  //
  // TWO boxes describe one card, in two units, and keeping them straight IS the fix:
  //   `offset` — SCREEN px from the anchor's centre. What the card RENDERS at. Zoom-free, so the card
  //              cannot drift during a wheel gesture that React has not committed yet.
  //   `rect`   — the WORLD area the card covers at the current zoom. What the neighbour push READS.
  //              Zoom-dependent by definition: a fixed screen size covers more world as you zoom out.
  const offset = cellOffset(at, cell);
  const rect = useMemo(
    () => cellRect(anchorNode, at, cell, zoom || 1),
    [anchorNode, at, cell, zoom],
  );

  // The ANCHOR element's counter-scale. A layout effect, not a ref callback, so it re-registers cleanly
  // if the hook identity ever changes, and unregisters on unmount — several morphs are open at once and
  // a leaked registration would keep writing a transform onto a detached node.
  const anchorRef = useRef<HTMLDivElement | null>(null);
  useLayoutEffect(() => {
    const el = anchorRef.current;
    if (!el || !counterScale) return;
    return counterScale(el);
  }, [counterScale]);
  const [resizing, setResizing] = useState(false);
  const closingRef = useRef(false);
  // The pending grow→collapse→onClose timer. Held in a ref so we can CANCEL it if this morph unmounts
  // before it fires (#3049) — e.g. the user clicks another live node, which remounts a FRESH morph for
  // it (keyed by paneId). Without this, the old morph's delayed onClose (setChatNode(null)) fires ~420ms
  // later and clobbers the newly-grown node, collapsing everything instead of switching.
  const exitTimer = useRef<number | null>(null);

  // Grow to the expanded box on the next frame; the CSS transition tweens the world geometry.
  useLayoutEffect(() => {
    const id = requestAnimationFrame(() => setOpen(true));
    return () => cancelAnimationFrame(id);
  }, []);

  // Report the live box up while open; clear it on collapse + on unmount (so neighbours snap back).
  useEffect(() => {
    onRect?.(open && !closingRef.current ? rect : null);
  }, [open, rect, onRect]);
  useEffect(() => () => onRect?.(null), [onRect]);
  // Cancel a pending exit on unmount so a superseded morph's onClose can't fire after it's gone (#3049).
  useEffect(() => () => { if (exitTimer.current != null) window.clearTimeout(exitTimer.current); }, []);

  const close = () => {
    if (closingRef.current) return;
    closingRef.current = true;
    onRect?.(null);                       // release the neighbours immediately
    setOpen(false);                       // shrink back into the node
    exitTimer.current = window.setTimeout(onClose, EXIT_MS);  // unmount after the transition (or immediately, reduced-motion)
  };

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") close(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // A CLICK anywhere OUTSIDE the card closes it (#2537). We do NOT use a scrim — that would swallow the
  // graph's own gestures — so we listen at the window (capture phase, before any stopPropagation) and
  // decide on mouseUP: only a press-release that STAYED put is a click. A press that DRAGGED past the
  // viewport's own 4px pan threshold is a pan (or a terminal text-selection), so the graph keeps
  // panning/zooming/selecting and the card stays open.
  //
  // TWO kinds of press are exempt (#3365):
  //  • inside ANY `.glance-card` — every morph shares the class, so with several open a click in one
  //    card dismisses none of them (including this one).
  //  • on a graph NODE (`[data-glance-node]`) — clicking a node is a deliberate OPEN/SELECT gesture,
  //    not a dismiss. Without this, opening a second node tore down the first: the press on node B is
  //    outside A's card, so A closed the moment B opened, and only one morph was ever visible. That
  //    silently defeated the whole multi-open grid (#3361).
  // Empty canvas is neither, so a click on the backdrop still dismisses everything.
  useEffect(() => {
    let start: { x: number; y: number } | null = null;
    const onDown = (e: MouseEvent) => {
      const t = e.target as HTMLElement | null;
      const exempt = !!t?.closest(".glance-card") || !!t?.closest("[data-glance-node]");
      start = exempt ? null : { x: e.clientX, y: e.clientY };
    };
    const onUp = (e: MouseEvent) => {
      if (!start) return;
      const moved = Math.abs(e.clientX - start.x) + Math.abs(e.clientY - start.y);
      start = null;
      if (moved <= 4) close(); // a click, not a drag/pan
    };
    window.addEventListener("mousedown", onDown, true);
    window.addEventListener("mouseup", onUp, true);
    return () => {
      window.removeEventListener("mousedown", onDown, true);
      window.removeEventListener("mouseup", onUp, true);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Edge/corner resize: track the pointer at the window (robust across the whole drag). The geometry
  // tween is suppressed WHILE dragging so it tracks the pointer 1:1.
  //
  // THE DELTA IS NO LONGER DIVIDED BY THE ZOOM. It used to be, because the cell was world units and the
  // card scaled with the graph. Now the cell IS screen px and so is the card, so a pointer pixel is a
  // card pixel — the handle tracks the cursor exactly, at every zoom, which it never did before. (The
  // division was also reading the stale `zoom` prop, so a resize begun during a wheel gesture scaled the
  // drag by the wrong factor.)
  //
  // #3361: a drag resizes the grid's SHARED CELL, not this one card, so every open morph grows together
  // and the grid stays a grid. A west/north drag therefore only INVERTS the delta (grow as the pointer
  // moves left/up) — it can no longer move the card's origin, which the lattice owns.
  const startResize = (dir: string) => (e: React.PointerEvent) => {
    e.stopPropagation();
    e.preventDefault();
    setResizing(true);
    const sx = e.clientX, sy = e.clientY, s = cell;
    const move = (ev: PointerEvent) => {
      const dx = ev.clientX - sx, dy = ev.clientY - sy;
      let { w, h } = s;
      if (dir.includes("e")) w = s.w + dx;
      if (dir.includes("w")) w = s.w - dx;
      if (dir.includes("s")) h = s.h + dy;
      if (dir.includes("n")) h = s.h - dy;
      const c = clampCell(w, h);
      onResizeCell?.(c.w, c.h);
    };
    const up = () => {
      setResizing(false);
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
  };

  // The card's box, in SCREEN px, relative to the anchor element's origin (the anchor node's centre).
  //
  //   OPEN      — the lattice cell: `offset` is its centre, so back off half the cell to get the corner.
  //               No zoom term at all, which is what makes an open card immovable during a wheel gesture.
  //   COLLAPSED — the node's own on-screen box, so the grow starts (and the shrink ends) exactly on the
  //               node. This one MUST convert, because the node is drawn in world units — and it is the
  //               only place the possibly-stale `zoom` is acceptable: it is a transition endpoint, so a
  //               120ms-old scale can only mean a 420ms animation that starts a hair off, never a click
  //               landing on the wrong cell.
  const z = zoom || 1;
  const box = open
    ? { left: offset.dx - cell.w / 2, top: offset.dy - cell.h / 2, width: cell.w, height: cell.h }
    : {
      left: (node.x - anchorCentre(anchorNode).x) * z,
      top: (node.y - anchorCentre(anchorNode).y) * z,
      width: NW * z,
      height: NH * z,
    };

  return (
    // THE ANCHOR: positioned in WORLD coords (so it pans with the graph) and carrying the inverse of the
    // world scale, written by `vp.counterScale`. Zero-size on purpose — it is a coordinate origin, not a
    // container — so it clips nothing and the card simply overflows it.
    //
    // `transform` is deliberately ABSENT from this style object. The hook writes it imperatively and
    // re-applies it after every render; naming it here too would give React a second opinion about the
    // one value that must never disagree with the world layer.
    //
    // `zIndex` sits HERE rather than only on the card: a `transform` creates a stacking context, so the
    // card's own z-index now competes inside this element rather than against the graph's nodes.
    //
    // A raw `div`, not a `Box`, for the same reason the world layer is one (#4140): `Box` does not
    // forward a ref, and this needs a REAL DOM node for the hook to write a transform onto.
    // eslint-disable-next-line no-restricted-syntax -- needs a real DOM ref for the imperative counter-scale
    <div
      ref={anchorRef}
      style={{ position: "absolute", left: anchorCentre(anchorNode).x, top: anchorCentre(anchorNode).y, transformOrigin: "0 0", zIndex: 20 }}
    >
      {/* THE CARD: screen px inside the counter-scaled anchor, so its net CSS scale is 1 and the xterm
          inside it hit-tests correctly. Still animates left/top/width/height, so `glance.css` is
          untouched. Pointer events stopPropagation so interacting with the terminal never starts a
          canvas pan / deselect. */}
      <Box
        className={`glance-card${open ? " open" : ""}`}
        role="dialog" aria-label={`${name} session`}
        onMouseDown={(e) => e.stopPropagation()}
        onClick={(e) => e.stopPropagation()}
        style={{ position: "absolute", left: box.left, top: box.top, width: box.width, height: box.height,
          // While actively resizing, drop the geometry tween so the panel tracks the pointer 1:1.
          ...(resizing ? { transition: "none" } : null) }}
      >
        <Box className="glance-card-body">
          <GlanceChatDock paneId={paneId} name={name} role={role} plan={plan} onClose={close} onEnd={onEnd} />
        </Box>
        {open ? HANDLES.map((hnd) => (
          <Box
            key={hnd.dir}
            as="div"
            onPointerDown={startResize(hnd.dir)}
            aria-label={`Resize ${hnd.dir}`}
            style={{ position: "absolute", zIndex: 4, ...hnd.style }}
          />
        )) : null}
      </Box>
    </div>
  );
}
